<template>
    <div :class="['shell', { amphi: projectorMode }]">
          <header class="topbar">
                  <div class="brand" @click="activeView = 'landing'">
                            <span class="ets">éTS</span>
                                    <div>
                                                <strong>MAT145 Studio v2.0</strong>
                                                          <small>Calcul différentiel et intégral • éTS Montréal</small>
                                                                  </div>
                                                                        </div>
                                                                              <nav class="tabs">
                                                                                        <button :class="{ active: activeView === 'landing' }" @click="activeView = 'landing'">✨ Accueil</button>
                                                                                                <button :class="{ active: activeView === 'studio' }" @click="openLab(activeLab)">📐 Studio Interactif (4 Labs)</button>
                                                                                                      </nav>
                                                                                                            <button class="amphi-btn" @click="projectorMode = !projectorMode">📽️ Mode Amphithéâtre</button>
                                                                                                                </header>
                                                                                                                
          <main v-if="activeView === 'landing'" class="landing">
                  <div class="hero">
                            <div class="hero-text">
                                        <span class="pill">● éCOLE DE TECHNOLOGIE SUPéRIEURE • MAT145</span>
                                                  <h1>Visualisez le <span class="grad">Calcul Différentiel et Intégral</span> en Temps Réel.</h1>
                                                            <p>Laboratoire interactif 60 FPS pour illustrer la dérivée (h → 0), les sommes de Riemann, les solides de révolution 3D (disques et rondelles) et les séries de Taylor.</p>
                                                                      <button class="cta" @click="openLab('derivative')">🚀 Ouvrir le Studio Interactif →</button>
                                                                              </div>
                                                                                      <div class="bento">
                                                                                                  <div v-for="m in modules" :key="m.id" class="card" @click="openLab(m.id)">
                                                                                                                <span class="tag">{{ m.code }}</span>
                                                                                                                            <h3>{{ m.title }}</h3>
                                                                                                                                        <p>{{ m.desc }}</p>
                                                                                                                                                    <code>{{ m.eq }}</code>
                                                                                                                                                              </div>
                                                                                                                                                                      </div>
                                                                                                                                                                            </div>
                                                                                                                                                                                </main>
                                                                                                                                                                                
          <main v-else class="studio">
                  <div class="mod-bar">
                            <button v-for="m in modules" :key="m.id" :class="{ active: activeLab === m.id }" @click="openLab(m.id)">
                                        {{ m.code }} — {{ m.title }}
                                      </button>
                                            </div>
                                                  <div class="workspace">
                                                            <div class="canvas-wrap">
                                                                        <canvas ref="cv" width="820" height="500"></canvas>
                                                                                  <div class="hud">{{ hudText }}</div>
                                                                                          </div>
                                                                                                  <div class="panel">
                                                                                                              <h3>⚙️ Paramètres Temps Réel</h3>
                                                                                                                        <template v-if="activeLab === 'derivative'">
                                                                                                                                      <label>Point de tangence a : {{ a.toFixed(2) }}
                                                                                                                                                      <input type="range" v-model.number="a" min="-2.5" max="2.5" step="0.05" @input="draw" />
                                                                                                                                                    </label>
                                                                                                                                                                <label>Pas Δx (h) : {{ h.toFixed(3) }}
                                                                                                                                                                                <input type="range" v-model.number="h" min="0.01" max="2.0" step="0.01" @input="draw" />
                                                                                                                                                                              </label>
                                                                                                                                                                                          <button class="cta" @click="animH">▶ Animer h → 0</button>
                                                                                                                                                                                                    </template>
                                                                                                                                                                                                              <template v-else-if="activeLab === 'riemann'">
                                                                                                                                                                                                                            <label>Nombre de rectangles n : {{ n }}
                                                                                                                                                                                                                                            <input type="range" v-model.number="n" min="2" max="80" step="1" @input="draw" />
                                                                                                                                                                                                                                          </label>
                                                                                                                                                                                                                                                    </template>
                                                                                                                                                                                                                                                              <template v-else-if="activeLab === 'revolution'">
                                                                                                                                                                                                                                                                            <label>Angle de rvolution θ : {{ theta }}°
                                                                                                                                                                                                                                                                                            <input type="range" v-model.number="theta" min="20" max="360" step="5" @input="draw" />
                                                                                                                                                                                                                                                                                          </label>
                                                                                                                                                                                                                                                                                                      <label>Position rondelle x_k : {{ sliceX.toFixed(2) }}
                                                                                                                                                                                                                                                                                                                      <input type="range" v-model.number="sliceX" min="0.4" max="3.4" step="0.1" @input="draw" />
                                                                                                                                                                                                                                                                                                                    </label>
                                                                                                                                                                                                                                                                                                                              </template>
                                                                                                                                                                                                                                                                                                                                        <template v-else>
                                                                                                                                                                                                                                                                                                                                                      <label>Degré du polynôme de Taylor k : {{ deg }}
                                                                                                                                                                                                                                                                                                                                                                      <input type="range" v-model.number="deg" min="1" max="13" step="2" @input="draw" />
                                                                                                                                                                                                                                                                                                                                                                    </label>
                                                                                                                                                                                                                                                                                                                                                                              </template>
                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                </main>
                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                  </templa
                                                                                                                                                                                                                                                                                                                                                                                                    <script setup>
                                                                                                                                                                                                                                                                                                                                                                                                      import { ref, nextTick } from 'vue';
                                                                                                                                                                                                                                                                                                                                                                                                      const activeView = ref('landing');
                                                                                                                                                                                                                                                                                                                                                                                                      const activeLab = ref('derivative');
                                                                                                                                                                                                                                                                                                                                                                                                      const projectorMode = ref(false);
                                                                                                                                                                                                                                                                                                                                                                                                      const cv = ref(null);
                                                                                                                                                                                                                                                                                                                                                                                                      const hudText = ref('');
                                                                                                                                                                                                                                                                                                                                                                                                      const a = ref(1.0), h = ref(1.1), n = ref(12), theta = ref(270), sliceX = ref(2.0), deg = ref(5);
                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                      const modules = [
                                                                                                                                                                                                                                                                                                                                                                                                          { id: 'derivative', code: 'LAB 01', title: 'Dérivée & Tangente', desc: 'Convergence de la sécante vers la tangente exacte.', eq: "f'(a) = lim_{h→0} [f(a+h)-f(a)]/h" },
                                                                                                                                                                                                                                                                                                                                                                                                          { id: 'riemann', code: 'LAB 02', title: 'Sommes de Riemann', desc: 'Partition et convergence vers l’intégrale définie.', eq: '∫ f(x)dx = lim Σ f(x_i*)Δx' },
                                                                                                                                                                                                                                                                                                                                                                                                          { id: 'revolution', code: 'LAB 03', title: 'Solides 3D & Rondelles', desc: 'Révolution 3D avec rayon externe R(x) et interne r(x).', eq: 'V = π ∫ ([R(x)]² - [r(x)]²) dx' },
                                                                                                                                                                                                                                                                                                                                                                                                          { id: 'taylor', code: 'LAB 04', title: 'Séries de Taylor', desc: 'Approximation polynomiale et convergence.', eq: 'P_n(x) = Σ f^(k)(0)/k! x^k' }
                                                                                                                                                                                                                                                                                                                                                                                                        ];
                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                      function openLab(id) { activeLab.value = id; activeView.value = 'studio'; nextTick(draw); }
                                                                                                                                                                                                                                                                                                                                                                                                      function animH() {
                                                                                                                                                                                                                                                                                                                                                                                                          h.value = 2.0;
                                                                                                                                                                                                                                                                                                                                                                                                          const step = () => { if (h.value > 0.02) { h.value *= 0.92; draw(); requestAnimationFrame(step); } };
                                                                                                                                                                                                                                                                                                                                                                                                          requestAnimationFrame(step);
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                      function fact(k) { let r = 1; for (let i = 2; i <= k; i++) r *= i; return r; }
                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                      function draw() {
                                                                                                                                                                                                                                                                                                                                                                                                          if (!cv.value) return;
                                                                                                                                                                                                                                                                                                                                                                                                          const ctx = cv.value.getContext('2d'), w = 820, ht = 500;
                                                                                                                                                                                                                                                                                                                                                                                                          ctx.fillStyle = '#060a14'; ctx.fillRect(0, 0, w, ht);
                                                                                                                                                                                                                                                                                                                                                                                                          ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.5;
                                                                                                                                                                                                                                                                                                                                                                                                          ctx.beginPath(); ctx.moveTo(0, ht/2); ctx.lineTo(w, ht/2); ctx.moveTo(w/2, 0); ctx.lineTo(w/2, ht); ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                          if (activeLab.value === 'derivative') {
                                                                                                                                                                                                                                                                                                                                                                                                                const f = x => 0.3*x*x*x - x + 0.5, df = x => 0.9*x*x - 1;
                                                                                                                                                                                                                                                                                                                                                                                                                const ox = w/2, oy = ht/2, sx = 95, sy = 75;
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 3; ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                for (let px = 0; px < w; px += 3) {
                                                                                                                                                                                                                                                                                                                                                                                                                        const x = (px - ox)/sx, py = oy - f(x)*sy;
                                                                                                                                                                                                                                                                                                                                                                                                                        px === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                const fa = f(a.value), fah = f(a.value + h.value), ms = (fah - fa)/h.value, mt = df(a.value);
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2; ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.moveTo(0, oy - (fa + ms*(-ox/sx - a.value))*sy); ctx.lineTo(w, oy - (fa + ms*((w-ox)/sx - a.value))*sy); ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.fillStyle = '#ef3e42'; ctx.beginPath(); ctx.arc(ox + a.value*sx, oy - fa*sy, 6, 0, 7); ctx.fill();
                                                                                                                                                                                                                                                                                                                                                                                                                hudText.value = `a = ${a.value.toFixed(2)} | h = ${h.value.toFixed(3)} | Pente sécante = ${ms.toFixed(3)} | f'(a) = ${mt.toFixed(3)}`;
                                                                                                                                                                                                                                                                                                                                                                                                              } else if (activeLab.value === 'riemann') {
                                                                                                                                                                                                                                                                                                                                                                                                                const f = x => Math.sin(x) + 1.3, dx = 4.0 / n.value, ox = 80, oy = ht - 70, sx = 150, sy = 130;
                                                                                                                                                                                                                                                                                                                                                                                                                let sum = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                for (let i = 0; i < n.value; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                        const xm = (i + 0.5)*dx, ym = f(xm); sum += ym*dx;
                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.fillStyle = 'rgba(56,189,248,0.25)'; ctx.strokeStyle = '#38bdf8';
                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.fillRect(ox + i*dx*sx, oy - ym*sy, dx*sx - 2, ym*sy);
                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.strokeRect(ox + i*dx*sx, oy - ym*sy, dx*sx - 2, ym*sy);
                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                hudText.value = `Rectangles n = ${n.value} | Somme de Riemann S_n = ${sum.toFixed(4)}`;
                                                                                                                                                                                                                                                                                                                                                                                                              } else if (activeLab.value === 'revolution') {
                                                                                                                                                                                                                                                                                                                                                                                                                const cx = w*0.45, cy = ht*0.52, sc = 75, maxT = theta.value*Math.PI/180;
                                                                                                                                                                                                                                                                                                                                                                                                                for (let i = 0; i < 18; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                        const x = i*0.2, R = Math.sqrt(x) + 0.5;
                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.strokeStyle = 'rgba(56,189,248,0.35)'; ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                        for (let j = 0; j <= 24; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                  const t = (j/24)*maxT, px = cx + (x*0.8 + R*Math.sin(t)*0.4)*sc, py = cy - (R*Math.cos(t)*0.85)*sc;
                                                                                                                                                                                                                                                                                                                                                                                                                                  j === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                hudText.value = `Révolution 3D : θ = ${theta.value}° | Tranche x_k = ${sliceX.value.toFixed(2)}`;
                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                const ox = w/2, oy = ht/2, sx = 75, sy = 90;
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 3; ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                for (let px = 0; px < w; px += 3) { const x = (px-ox)/sx; px===0 ? ctx.moveTo(px, oy-Math.sin(x)*sy) : ctx.lineTo(px, oy-Math.sin(x)*sy); }
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2.5; ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                for (let px = 0; px < w; px += 3) {
                                                                                                                                                                                                                                                                                                                                                                                                                        const x = (px-ox)/sx; let s = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                        for (let k = 1; k <= deg.value; k += 2) s += (((k-1)/2)%2===0 ? 1 : -1)*Math.pow(x,k)/fact(k);
                                                                                                                                                                                                                                                                                                                                                                                                                        const py = Math.max(-50, Math.min(ht+50, oy - s*sy));
                                                                                                                                                                                                                                                                                                                                                                                                                        px===0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                hudText.value = `Série de Taylor de sin(x) | Ordre polynomial n = ${deg.value}`;
                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                      </script>
  te>
  <style scoped>
    .shell { min-height: 100vh; background: #050811; color: #f8fafc; font-family: system-ui, sans-serif; }
    .shell.amphi { font-size: 115%; }
    .topbar { display: flex; justify-content: space-between; align-items: center; padding: 14px 28px; border-bottom: 1px solid #1e293b; background: #090e1a; }
