    .tabs button, .amphi-btn, .mod-bar button { background: #131c31; color: #cbd5e1; border: 1px solid #1e293b; padding: 8px 16px; border-radius: 8px; margin: 0 4px; cursor: pointer; font-weight: 600; }
    .tabs button.active, .mod-bar button.active, .cta { background: #ef3e42; color: #fff; border-color: #ef3e42; }
    .landing, .studio { max-width: 1280px; margin: 0 auto; padding: 36px 24px; }
    .pill { color: #fca5a5; background: rgba(239,62,66,0.12); padding: 5px 12px; border-radius: 99px; font-size: 12px; font-weight: 700; }
    .hero h1 { font-size: 46px; font-weight: 900; margin: 16px 0; line-height: 1.1; }
    .grad { color: #38bdf8; }
    .cta { padding: 12px 22px; border-radius: 10px; font-weight: 700; cursor: pointer; border: none; margin-top: 14px; }
    .bento { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; margin-top: 36px; }
    .card { background: #131c31; border: 1px solid #1e293b; padding: 22px; border-radius: 14px; cursor: pointer; transition: 0.2s; }
    .card:hover { border-color: #38bdf8; transform: translateY(-3px); }
    .tag { color: #38bdf8; font-family: monospace; font-size: 12px; font-weight: 700; }
    .card code { display: block; margin-top: 12px; padding: 8px; background: #050811; color: #fbbf24; border-radius: 6px; }
    .workspace { display: grid; grid-template-columns: 1fr 320px; gap: 20px; margin-top: 20px; }
    .canvas-wrap { position: relative; background: #131c31; border: 1px solid #1e293b; border-radius: 14px; overflow: hidden; }
    canvas { width: 100%; height: auto; display: block; }
    .hud { position: absolute; top: 12px; left: 12px; background: rgba(5,8,17,0.88); padding: 8px 14px; border-radius: 8px; font-family: monospace; font-size: 13px; color: #38bdf8; border: 1px solid #1e293b; }
    .panel { background: #131c31; border: 1px solid #1e293b; padding: 20px; border-radius: 14px; }
    .panel label { display: block; margin: 14px 0; font-size: 14px; }
    .panel input { width: 100%; margin-top: 6px; }
    </style>
                                                                                                                                                                                                                                                                                                                                                                                                  
